package com.afterglow.player;
import android.content.Context;import android.util.Base64;import android.security.keystore.*;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;
/** The search credential is encrypted with a non-exportable Android Keystore key. */
final class KeyStore {
 static javax.crypto.SecretKey key()throws Exception{java.security.KeyStore store=java.security.KeyStore.getInstance("AndroidKeyStore");store.load(null);if(!store.containsAlias("afterglow-search")){KeyGenerator g=KeyGenerator.getInstance("AES","AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder("afterglow-search",KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());g.generateKey();}return (javax.crypto.SecretKey)store.getKey("afterglow-search",null);}
 static String load(Context c){return load(c,"search");} static String load(Context c,String name){try{String value=c.getSharedPreferences("credentials",0).getString(name,"");if(value.isEmpty())return "";String[] p=value.split(":");Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Base64.decode(p[0],0)));return new String(cipher.doFinal(Base64.decode(p[1],0)),"UTF-8");}catch(Exception e){return "";}}
 static void save(Context c,String value){save(c,"search",value);} static void save(Context c,String name,String value){if(value.isEmpty()){c.getSharedPreferences("credentials",0).edit().remove(name).commit();return;}try{Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key());String encrypted=Base64.encodeToString(cipher.getIV(),2)+":"+Base64.encodeToString(cipher.doFinal(value.getBytes("UTF-8")),2);if(!c.getSharedPreferences("credentials",0).edit().putString(name,encrypted).commit())throw new Exception();}catch(Exception e){throw new IllegalStateException("Could not save the API key securely. Please retry.");}}
}
